code.java:
class Solution {
    public long[] sumOfThree(long num){
        if(num%3!=0)return new long[0];
        long middle=num/3;
        return new long[]{
            middle-1,middle,middle+1
        };
    }
}

code.kotlin:
class Solution {
    fun sumOfThree(num:Long):LongArray{
        if(num%3L!=0L)return longArrayOf();
        val middle=num/3;
        return longArrayOf(middle-1,middle,middle+1)
    }
}

